UPDATE MEMBER
   SET LOCKED_UNTIL = CASE WHEN LOGIN_FAIL_COUNT + 1 >= #{maxFailCount}
                           THEN SYSDATE + NUMTODSINTERVAL(#{lockMinutes}, 'MINUTE')
                           ELSE LOCKED_UNTIL END,
       LOGIN_FAIL_COUNT = CASE WHEN LOGIN_FAIL_COUNT + 1 >= #{maxFailCount}
                               THEN 0
                               ELSE LOGIN_FAIL_COUNT + 1 END
 WHERE MEMBER_ID = #{memberId}
